export const MAX_FIG_THUMBNAIL_BYTES = 512 * 1024;
const LEGACY_LOCAL_COPY_MAGIC = new Uint8Array([
    0x66, 0x69, 0x67, 0x2d, 0x6b, 0x69, 0x77, 0x69,
]);
function unsupportedFigImport() {
    throw new Error("Legacy .fig helpers no longer process files locally. Connect Builder (free tier available) and use the design system indexing flow instead.");
}
export function looksLikeFigFile(data) {
    const isZip = data[0] === 0x50 &&
        data[1] === 0x4b &&
        data[2] === 0x03 &&
        data[3] === 0x04;
    const isLegacyLocalCopy = LEGACY_LOCAL_COPY_MAGIC.every((byte, index) => data[index] === byte);
    return isZip || isLegacyLocalCopy;
}
export function figThumbnailDataUrl(thumbnail) {
    if (!thumbnail || thumbnail.length > MAX_FIG_THUMBNAIL_BYTES)
        return null;
    return `data:image/png;base64,${thumbnail.toString("base64")}`;
}
